// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }
    function testFuzz_property(uint256 ts, uint256 bn, address actor) public {
        // keep params in the admissible domain: block number divisible by 15, timestamp strictly increasing
        bn = bound(bn, 15, 1 << 200);
        vm.assume(bn % 15 == 0);
        vm.assume(actor != address(0) && actor != address(c));
        vm.roll(bn);
        ts = bound(ts, block.timestamp + 1, 1 << 200);
        vm.warp(ts);

        vm.deal(actor, 10 ether);
        vm.prank(actor);
        // cannot name-call fallback; use the low-level entry point
        (bool ok,) = address(c).call{value: 10 ether}("");

        // General rule: an accepted 10-ether call on a divisible-by-15 block
        // must drain the contract's whole balance to the caller.
        assertTrue(ok && address(c).balance == 0);
    }
}
